package com.fitflow.activities;
import java.time.*;import java.time.temporal.ChronoUnit;import java.util.*;import org.springframework.http.*;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api") public class ActivityController{private final ActivityRepository repo;private final KafkaTemplate<String,ActivityEvent> kafka;public ActivityController(ActivityRepository r,KafkaTemplate<String,ActivityEvent> k){repo=r;kafka=k;}
 @PostMapping("/activities") public ResponseEntity<?> create(@AuthenticationPrincipal Jwt jwt,@RequestBody Activity a){if(a.type==null||a.type.isBlank()||a.duration<1||a.duration>1440||a.caloriesBurned<0||a.caloriesBurned>20000||a.startTime==null)return ResponseEntity.badRequest().body(Map.of("error","type, duration, caloriesBurned, and startTime are required and must be valid"));a.id=null;a.userId=jwt.getSubject();a.createdAt=Instant.now();a.additionalMetrics=a.additionalMetrics==null?new HashMap<>():a.additionalMetrics;Activity saved=repo.save(a);kafka.send("activity-events",saved.userId,new ActivityEvent(saved.id,saved.userId,saved.type,saved.duration,saved.caloriesBurned,saved.steps,saved.distanceKm,saved.averageHeartRate,saved.paceMinutesPerKm,saved.startTime));return ResponseEntity.status(201).body(saved);}
 @GetMapping("/activities") public List<Activity> activities(@AuthenticationPrincipal Jwt jwt){return repo.findByUserIdOrderByStartTimeDesc(jwt.getSubject());}
 @GetMapping("/dashboard") public Map<String,Object> dashboard(@AuthenticationPrincipal Jwt jwt){String user=jwt.getSubject();Instant week=Instant.now().minus(7,ChronoUnit.DAYS);List<Activity> all=repo.findByUserIdOrderByStartTimeDesc(user),recent=repo.findByUserIdAndStartTimeGreaterThanEqual(user,week);int minutes=recent.stream().mapToInt(x->x.duration).sum(),calories=recent.stream().mapToInt(x->x.caloriesBurned).sum(),steps=recent.stream().filter(x->x.steps!=null).mapToInt(x->x.steps).sum();double distance=recent.stream().filter(x->x.distanceKm!=null).mapToDouble(x->x.distanceKm).sum();return Map.of("weeklyWorkoutCount",recent.size(),"weeklyActiveMinutes",minutes,"weeklyCaloriesBurned",calories,"weeklySteps",steps,"weeklyDistanceKm",distance,"workoutStreak",streak(all),"goalProgress",Math.min(100,Math.round(minutes*100.0/150)),"recentActivities",all.stream().limit(5).toList());}
 private int streak(List<Activity> a){Set<LocalDate> days=new HashSet<>();for(Activity x:a)days.add(x.startTime.atZone(ZoneId.systemDefault()).toLocalDate());int n=0;for(LocalDate d=LocalDate.now();days.contains(d)||d.equals(LocalDate.now());d=d.minusDays(1)){if(days.contains(d))n++;else if(n>0)break;else break;}return n;}}

